{"record":"parent_entry","position":{"parent_record":"response:00000000000000000029:0001:0000","subposition":null},"original_role":"assistant","source":"tool_call","trust":"untrusted","provenance":null,"content":"{\"kind\":\"tool_call\",\"id\":\"fc_01a169ceb11f72339bcd81f68c82ad4a\",\"call_id\":\"call_01a169ceb11f72339bcd81f68c82ad4a\",\"name\":\"write_file\",\"arguments\":\"{\\\"content\\\":\\\"// Loads supabase-js from a pinned CDN ESM build (no bundler, no import map\\\\n// needed) and exposes a single client plus a minimal session bridge for the\\\\n// classic chat script in app.js.\\\\n\\\\nconst SUPABASE_JS_URL = 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';\\\\n\\\\nlet clientPromise = null;\\\\n\\\\nasync function loadClient() {\\\\n  if (!clientPromise) {\\\\n    clientPromise = (async () => {\\\\n      const configResponse = await fetch('/config.json', { cache: 'no-store' });\\\\n      if (!configResponse.ok) {\\\\n        throw new Error('Could not load app configuration (/config.json).');\\\\n      }\\\\n      const config = await configResponse.json();\\\\n      if (!config.supabaseUrl || !config.supabaseAnonKey) {\\\\n        throw new Error('Supabase is not configured on the server.');\\\\n      }\\\\n      const { createClient } = await import(SUPABASE_JS_URL);\\\\n      return createClient(config.supabaseUrl, config.supabaseAnonKey, {\\\\n        auth: {\\\\n          persistSession: true,\\\\n          autoRefreshToken: true,\\\\n          detectSessionInUrl: true\\\\n        }\\\\n      });\\\\n    })();\\\\n  }\\\\n  return clientPromise;\\\\n}\\\\n\\\\nlet accessToken = null;\\\\nlet currentUser = null;\\\\nconst listeners = new Set();\\\\n\\\\nfunction notify() {\\\\n  listeners.forEach((listener) => {\\\\n    try {\\\\n      listener({ accessToken, user: currentUser });\\\\n    } catch {\\\\n      // Listener errors must never break session tracking.\\\\n    }\\\\n  });\\\\n}\\\\n\\\\nloadClient()\\\\n  .then((client) => {\\\\n    client.auth.getSession().then(({ data }) => {\\\\n      accessToken = data.session?.access_token || null;\\\\n      currentUser = data.session?.user || null;\\\\n      notify();\\\\n    });\\\\n    client.auth.onAuthStateChange((_event, session) => {\\\\n      accessToken = session?.access_token || null;\\\\n      currentUser = session?.user || null;\\\\n      notify();\\\\n    });\\\\n  })\\\\n  .catch((error) => {\\\\n    console.error('Supabase client failed to initialize:', error);\\\\n  });\\\\n\\\\nexport function getSupabaseClient() {\\\\n  return loadClient();\\\\n}\\\\n\\\\nexport function getAccessToken() {\\\\n  return accessToken;\\\\n}\\\\n\\\\nexport function getCurrentUser() {\\\\n  return currentUser;\\\\n}\\\\n\\\\nexport function onAuthChange(listener) {\\\\n  listeners.add(listener);\\\\n  return () => listeners.delete(listener);\\\\n}\\\\n\\\\nif (!window.AppAuth) {\\\\n  window.AppAuth = {};\\\\n}\\\\nwindow.AppAuth.getSupabaseClient = getSupabaseClient;\\\\nwindow.AppAuth.getAccessToken = getAccessToken;\\\\nwindow.AppAuth.getCurrentUser = getCurrentUser;\\\\nwindow.AppAuth.onAuthChange = onAuthChange;\\\\n\\\",\\\"path\\\":\\\"supabaseClient.js\\\"}\"}","truncated":false}
